const sessionActivityKey = "lifewood-session-activity";
const sessionIdleTimeoutMs = 30 * 60_000;
const sessionNotice = sessionExitNotice;

const recordSessionActivity = () => {
  try {
    window.localStorage.setItem(sessionActivityKey, String(Date.now()));
  } catch {
    /* Storage can be unavailable in privacy mode. */
  }
};

const lastSessionActivity = () => {
  try {
    return Number(window.localStorage.getItem(sessionActivityKey) || 0);
  } catch {
    return 0;
  }
};

