const s = (value: unknown) =>
  value === null || value === undefined ? "" : String(value);
const n = (value: unknown) => Number(value ?? 0);
const parseJson = <T,>(value: unknown, fallback: T): T => {
  try {
    return JSON.parse(s(value)) as T;
  } catch {
    return fallback;
  }
};
const formatTimecode = (seconds: number) => {
  const total = Math.max(0, Math.floor(seconds));
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const remainder = total % 60;
  return [hours, minutes, remainder]
    .map((value) => String(value).padStart(2, "0"))
    .join(":");
};
// Business codes remain available for database lookup and search, but primary UI labels stay human-readable.
const codedName = (_code: unknown, name: unknown) => s(name);
const formatDate = (value: unknown, locale: Locale) =>
  value
    ? new Intl.DateTimeFormat(locale === "zh" ? "zh-CN" : "en-GB", {
        year: "numeric",
        month: "short",
        day: "2-digit",
      }).format(new Date(s(value)))
    : "—";
const formatDateTime = (value: unknown, locale: Locale) =>
  value
    ? new Intl.DateTimeFormat(locale === "zh" ? "zh-CN" : "en-GB", {
        year: "numeric",
        month: "short",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
      }).format(new Date(s(value)))
    : "—";
const formatSize = (value: unknown) => {
  const bytes = n(value);
  if (!bytes) return "0 B";
  const units = ["B", "KB", "MB", "GB"];
  const unit = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), 3);
  return `${(bytes / 1024 ** unit).toFixed(unit > 1 ? 1 : 0)} ${units[unit]}`;
};
function uploadResponse(status: number, responseText: string): { phase: UploadPhase; result: UploadResult } {
  let result: UploadResult = {};
  try { result = JSON.parse(responseText) as UploadResult; } catch { /* An unreadable response cannot confirm a write. */ }
  if (status >= 200 && status < 300 && result?.ok === true)
    return { phase: "completed", result };
  if(result?.code==="UPLOAD_UNCONFIRMED")return {phase:"unconfirmed",result:{...result,ok:false,disposition:"unconfirmed"}};
  if (status >= 400 && status < 500)
    return { phase: "failed", result: { ...result, ok: false, disposition: "failed", error: result?.error || "Upload failed." } };
  return { phase: "unconfirmed", result: { ok: false, disposition: "unconfirmed", error: "Upload result is unconfirmed. Refresh the destination folder and check for the file before retrying." } };
}
const uploadPhaseText = (task: ProgressTask, locale: Locale) => {
  if (task.phase === "preparing")
    return locale === "zh" ? "正在生成视频预览图" : "Preparing video preview";
  if (task.phase === "uploading" && task.progress < 0) return locale === "zh" ? "正在上传并保存" : "Uploading and saving";
  if (task.phase === "uploading")
    return locale === "zh"
      ? `上传中 ${task.progress}%`
      : `Uploading ${task.progress}%`;
  if (task.phase === "verifying")
    return locale === "zh" ? "校验并保存中" : "Verifying and saving";
  if (task.phase === "completed")
    return locale === "zh" ? "已完成" : "Completed";
  if (task.phase === "interrupted" || task.phase === "unconfirmed")
    return locale === "zh"
      ? "上传结果暂未确认，请先刷新查看目标文件夹，确认不存在后再重试。"
      : "Upload result is unconfirmed. Refresh the destination folder and check for the file before retrying.";
  return task.error
    ? localizedError(task.error, locale)
    : locale === "zh"
      ? "上传失败，请重试"
      : "Upload failed; please retry";
};

function createVideoPoster(source: File | string, signal?: AbortSignal):Promise<Blob|null> {
  if(typeof source==="string"&&source.startsWith("/api/")&&directTransferEnabled()){
    return coverAccess(source, signal ?? new AbortController().signal).then(access =>
      access.kind === "ok" && !signal?.aborted ? createVideoPoster(access.url, signal) : null);
  }
  return new Promise<Blob | null>((resolve) => {
    if (signal?.aborted) return resolve(null);
    const video = document.createElement("video");
    if(typeof source==="string"&&source.startsWith("https://"))video.crossOrigin="anonymous";
    const objectUrl = source instanceof File ? URL.createObjectURL(source) : "";
    const sourceUrl = typeof source === "string" ? source : objectUrl;
    let settled = false;
    let timer = 0;
    const finish = (blob: Blob | null) => {
      if (settled) return;
      settled = true;
      window.clearTimeout(timer);
      signal?.removeEventListener("abort", abort);
      video.pause();
      video.removeAttribute("src");
      video.load();
      video.remove();
      if (objectUrl) URL.revokeObjectURL(objectUrl);
      resolve(blob);
    };
    const abort = () => finish(null);
    const capture = () => {
      if (!video.videoWidth || !video.videoHeight) return finish(null);
      const width = Math.min(640, video.videoWidth);
      const height = Math.max(
        1,
        Math.round((width * video.videoHeight) / video.videoWidth),
      );
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      canvas.getContext("2d")?.drawImage(video, 0, 0, width, height);
      canvas.toBlob((blob) => finish(blob), "image/jpeg", 0.84);
    };
    const captureDecodedFrame = async () => {
      const frameVideo = video as HTMLVideoElement & {
        requestVideoFrameCallback?: (callback: () => void) => number;
      };
      // A detached, paused video can report `seeked` while Chromium still has
      // no composited frame. Briefly playing a muted, off-screen element forces
      // an actual decoded frame, while the timeout keeps Safari/older engines
      // from waiting forever for requestVideoFrameCallback.
      try {
        await video.play();
      } catch {
        // Muted playback normally succeeds; the timed fallback below still
        // captures on browsers whose autoplay policy rejects programmatic play.
      }
      await new Promise<void>((done) => {
        let completed = false;
        const complete = () => {
          if (completed) return;
          completed = true;
          done();
        };
        window.setTimeout(complete, 350);
        if (frameVideo.requestVideoFrameCallback)
          frameVideo.requestVideoFrameCallback(complete);
        else
          window.requestAnimationFrame(() =>
            window.requestAnimationFrame(complete),
          );
      });
      video.pause();
      capture();
    };
    timer = window.setTimeout(() => finish(null), 20000);
    // Cancellation tears the decoder down instead of letting it run to the deadline.
    signal?.addEventListener("abort", abort, { once: true });
    video.muted = true;
    video.playsInline = true;
    video.preload = "auto";
    video.style.position = "fixed";
    video.style.left = "-10000px";
    video.style.top = "0";
    video.style.width = "2px";
    video.style.height = "2px";
    video.style.opacity = "0";
    video.style.pointerEvents = "none";
    document.body.appendChild(video);
    video.addEventListener("error", () => finish(null), { once: true });
    video.addEventListener(
      "loadeddata",
      () => {
        const target =
          Number.isFinite(video.duration) && video.duration > 0
            ? Math.min(1, Math.max(0.05, video.duration * 0.08))
            : 0;
        if (target > 0) {
          video.addEventListener("seeked", captureDecodedFrame, { once: true });
          video.currentTime = target;
        } else captureDecodedFrame();
      },
      { once: true },
    );
    video.src = sourceUrl;
    video.load();
  });
}

type StoredPosterResult = { ok: boolean; frame: Blob | null; cancelled?: boolean };
type PosterJob = { promise: Promise<StoredPosterResult>; controller: AbortController; waiters: number };
const videoPosterJobs = new Map<string, PosterJob>();
// A valid black/white frame stays black/white after regeneration. Keep this
// repair allowance outside revision-keyed components so refreshes cannot loop.
// Cap metadata as well: further versions can still use the local frame cover.
const repairedPosterVersions = new Set<string>();
const automaticPosterRepairLimit = 512;
function claimPosterRepair(versionId: string) {
  if (repairedPosterVersions.has(versionId) || repairedPosterVersions.size >= automaticPosterRepairLimit) return false;
  repairedPosterVersions.add(versionId);
  return true;
}
onCoverSessionReset(() => {
  for (const job of videoPosterJobs.values()) job.controller.abort();
  videoPosterJobs.clear();
  repairedPosterVersions.clear();
});
/**
 * Generates and stores a missing library poster. Only the decode holds the
 * page's single frame-grab slot; it is cancelled (request aborted, decoder
 * stopped) once every cover waiting for it has left the viewport. The upload
 * then runs on its own with the existing form submission and result check. A
 * frame that could not be stored (for example without library maintenance
 * rights) is returned for local display only.
 */
function ensureStoredVideoPoster(versionId: string, force = false, signal?: AbortSignal): Promise<StoredPosterResult> {
  const epoch = coverSessionEpoch();
  const automatic=force?undefined:automaticPreviewPending(versionId);
  if(automatic){
    // Do not download the newly uploaded original while its local-file poster
    // is being stored. Leaving the cover cancels only this display waiter.
    return new Promise(resolve=>{
      let settled=false;
      const finish=(result:StoredPosterResult)=>{if(settled)return;settled=true;signal?.removeEventListener('abort',leave);resolve(result);};
      const leave=()=>finish({ok:false,frame:null,cancelled:true});
      signal?.addEventListener('abort',leave,{once:true});if(signal?.aborted)return leave();
      void automatic.then(saved=>{
        if(settled)return;
        if(epoch!==coverSessionEpoch()||signal?.aborted)return leave();
        if(saved)return finish({ok:true,frame:null});
        void ensureStoredVideoPoster(versionId,false,signal).then(finish);
      });
    });
  }
  const jobKey = `${epoch}:${versionId}:${force ? "force" : "cached"}`;
  let job = videoPosterJobs.get(jobKey);
  if (job?.controller.signal.aborted) { videoPosterJobs.delete(jobKey); job = undefined; }
  if (!job) {
    const controller = new AbortController();
    const promise = frameGrabSlots.acquire(controller.signal)
      .then(async (release): Promise<StoredPosterResult> => {
        let blob: Blob | null;
        try { blob = await createVideoPoster(`/api/files?id=${encodeURIComponent(versionId)}`, controller.signal); }
        finally { release(); }
        if (controller.signal.aborted || epoch !== coverSessionEpoch()) return { ok: false, frame: null, cancelled: true };
        if (!blob) return { ok: false, frame: null };
        const data = new FormData();
        data.set("thumbnailForVersionId", versionId);
        if (force) data.set("forceThumbnail", "1");
        data.set("file", new File([blob], "preview.jpg", { type: "image/jpeg" }));
        const response = await fetch("/api/files", { method: "POST", body: data, signal: controller.signal }).catch(() => null);
        if (controller.signal.aborted || epoch !== coverSessionEpoch()) return { ok: false, frame: null, cancelled: true };
        return { ok: Boolean(response?.ok), frame: response?.ok ? null : blob };
      }, (): StoredPosterResult => ({ ok: false, frame: null, cancelled: true }))
      .catch((): StoredPosterResult => ({ ok: false, frame: null }));
    const created: PosterJob = { promise, controller, waiters: 0 };
    job = created;
    videoPosterJobs.set(jobKey, created);
    void promise.finally(() => { if (videoPosterJobs.get(jobKey) === created) videoPosterJobs.delete(jobKey); });
  }
  const shared = job;
  shared.waiters++;
  return new Promise(resolve => {
    let settled = false;
    const leave = () => {
      if (settled) return; settled = true;
      if (--shared.waiters === 0) shared.controller.abort();
      resolve({ ok: false, frame: null, cancelled: true });
    };
    if (signal?.aborted) return leave();
    signal?.addEventListener("abort", leave, { once: true });
    void shared.promise.then(result => {
      if (settled) return; settled = true;
      shared.waiters--; signal?.removeEventListener("abort", leave);
      resolve(result);
    });
  });
}

function videoPosterLooksBlank(image: HTMLImageElement) {
  try {
    const canvas = document.createElement("canvas");
    canvas.width = 16;
    canvas.height = 9;
    const context = canvas.getContext("2d", { willReadFrequently: true });
    if (!context || !image.naturalWidth || !image.naturalHeight) return true;
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    const pixels = context.getImageData(0, 0, canvas.width, canvas.height).data;
    let min = 255;
    let max = 0;
    let sum = 0;
    for (let index = 0; index < pixels.length; index += 4) {
      const luma =
        pixels[index] * 0.2126 +
        pixels[index + 1] * 0.7152 +
        pixels[index + 2] * 0.0722;
      min = Math.min(min, luma);
      max = Math.max(max, luma);
      sum += luma;
    }
    const average = sum / (pixels.length / 4);
    return max - min < 3 && (average < 4 || average > 251);
  } catch {
    return false;
  }
}
const accessLabel = (value: unknown, locale: Locale) =>
  ({
    client: locale === "zh" ? "销售" : "Sales",
    project: locale === "zh" ? "项目负责人" : "Project manager",
    production: locale === "zh" ? "剪辑师" : "Editor",
    quality: locale === "zh" ? "质检" : "Quality reviewer",
    system: locale === "zh" ? "管理员" : "Administrator",
  })[s(value)] ?? s(value);
const labelStatus = (value: unknown, locale: Locale) => {
  const raw = projectStatusLabel(value);
  const key = raw.toLowerCase();
  return locale === "zh"
    ? (exactChineseStatus[raw] ?? chineseStatus[key] ?? raw)
    : (englishStatus[raw] ?? englishStatus[key] ?? raw.replaceAll("_", " "));
};
const statusTone = (value: unknown) => {
  const raw = projectStatusLabel(value);
  const projectTone = projectStatusTone(raw);
  if (projectTone) return projectTone;
  const status = raw.toLowerCase();
  if (
    ["已交付", "已归档", "已受理"].includes(raw) ||
    [
      "approved",
      "qc_approved",
      "published",
      "active",
      "delivered",
      "confirmed",
      "accepted",
    ].includes(status)
  )
    return "ok";
  if (
    ["质检驳回", "客户要求修改", "部分语言待修改"].includes(raw) ||
    ["rejected", "disabled", "customer_revision_requested"].includes(status)
  )
    return "bad";
  if (
    [
      "待受理",
      "待补充资料",
      "待质检",
      "待客户预览",
      "待最终确认",
      "待交付",
    ].includes(raw) ||
    [
      "submitted",
      "needs_supplement",
      "pending review",
      "more information needed",
      "pending_qc",
      "follow-up",
      "pending",
      "pending pm review",
      "needs clarification",
    ].includes(status)
  )
    return "warn";
  return "neutral";
};
const isPastDue = (value: unknown, status?: unknown) => {
  if (["已交付", "已归档", "已终止"].includes(s(status))) return false;
  const date = s(value).slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return false;
  const today = new Date();
  const localToday = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}`;
  return date < localToday;
};

function projectDisplayStatus(project: Row) {
  const total = n(project.language_count);
  const returned = n(project.language_revision_count);
  if (total > 1 && returned > 0 && returned < total) return "部分语言待修改";
  return projectStatusLabel(project.workflow_status);
}

function reviewTaskLanguage(platform: Platform, row: Row) {
  const task = row.language_project_id ? platform.languages.find(item => item.id === row.language_project_id) : row;
  const name = s(row.language || task?.language);
  const code = s(row.language_code || task?.language_code);
  const projectId = row.project_id || task?.project_id;
  const linked = task?.source_system === "deseret_book" || platform.projects?.some(item => item.id === projectId && item.source_system === "deseret_book");
  return linked && code && code !== name ? [name, code].filter(Boolean).join(" · ") : name;
}

function languageRequirement(language: Row | null | undefined) {
  if (!language) return "";
  const expected = s(language.language).trim();
  const knownLanguages = new Set([
    "English",
    "English (US)",
    "Chinese",
    "Bahasa Melayu",
    "Thai",
    "Indonesian",
    "Vietnamese",
    "Japanese",
    "Korean",
    "Cantonese",
    "Spanish",
    "Portuguese",
    "Arabic",
    "英语",
    "英语（美国）",
    "中文",
    "马来语",
    "泰语",
    "印度尼西亚语",
    "越南语",
    "日语",
    "韩语",
    "粤语",
    "西班牙语",
    "葡萄牙语",
    "阿拉伯语",
    "繁体中文",
    "Chinese (Traditional)",
    "西班牙语（拉丁美洲）",
    "Spanish (Latin America)",
    "法语",
    "French",
    "德语",
    "German",
    "意大利语",
    "Italian",
    "阿拉伯语（未指定地区）",
    "Arabic (Unspecified region)",
    "印地语",
    "Hindi",
  ]);
  return s(language.requirements)
    .split("·")
    .map((part) => (knownLanguages.has(part.trim()) ? ` ${expected} ` : part))
    .join("·")
    .trim();
}

