function localizePlatformData(platform: Platform, locale: Locale): Platform {
  const translations = platform.nameTranslations || [];
  platform = { ...platform,
    projects: platform.projects.map(row => applyNameTranslation(row, "project", translations)),
    videos: platform.videos.map(row => applyNameTranslation(row, "video", translations)),
    projectRequests: platform.projectRequests.map(row => applyNameTranslation(row, "request", translations)),
  };
  const regionName = (value: unknown) =>
    customerRegionOptions.find(([item]) => item === s(value))?.[
      locale === "zh" ? 1 : 0
    ] ?? value;
  const industryName = (value: unknown) =>
    customerIndustryOptions.find(([item]) => item === s(value))?.[
      locale === "zh" ? 1 : 0
    ] ?? value;
  const languageName = (code: unknown, fallback: unknown) => languageLabel(code, fallback, locale);
  const clients: Row[] = platform.clients.map(client => ({
    ...client,
    source_name: client.name,
    source_legal_name: client.legal_name,
    source_contact_name: client.contact_name,
    source_region: client.region,
    source_industry: client.industry,
    name: businessTitle(applyNameTranslation(client, "client", translations), locale, "client"),
    legal_name: businessTitle(applyNameTranslation(client, "client_legal", translations), locale, "client_legal"),
    contact_name: businessTitle(applyNameTranslation(client, "contact", translations), locale, "contact"),
    region: regionName(client.region),
    industry: industryName(client.industry),
  }));
  const clientById = new Map(clients.map(client => [s(client.id), client]));
  const projects: Row[] = platform.projects.map(
    (project): Row => ({
      ...project,
      source_name: project.name,
      name: localizedProjectTitle(project, locale),
      [locale === "zh" ? "name_zh" : "name_en"]: localizedProjectTitle(project, locale),
      region: regionName(project.region),
      client_name: clientById.get(s(project.client_id))?.name ?? project.client_name,
    }),
  );
  const projectNameById = new Map(
    projects.map((project) => [s(project.id), s(project.name)]),
  );
  const projectById = new Map(
    projects.map((project) => [s(project.id), project]),
  );
  const videos: Row[] = platform.videos.map((video) => ({
    ...video,
    source_name: video.name,
    name: localizedVideoTitle(video, locale),
    [locale === "zh" ? "name_zh" : "name_en"]: localizedVideoTitle(video, locale),
  }));
  const videoById = new Map(videos.map((video) => [s(video.id), video]));
  const localizeProjectRows = (rows: Row[]): Row[] =>
    rows.map((row): Row => {
      const project = projectById.get(s(row.project_id));
      return {
        ...row,
        client_name: clientById.get(s(row.client_id || project?.client_id))?.name ?? row.client_name,
        project_name:
          projectNameById.get(s(row.project_id)) ?? s(row.project_name),
        project_name_zh: project?.name_zh ?? row.project_name_zh,
        project_name_en: project?.name_en ?? row.project_name_en,
        video_name:
          videoById.get(s(row.video_id))?.name ?? s(row.video_name),
        video_name_zh:
          videoById.get(s(row.video_id))?.name_zh ?? row.video_name_zh,
        video_name_en:
          videoById.get(s(row.video_id))?.name_en ?? row.video_name_en,
      };
    });
  const languages: Row[] = platform.languages.map(
    (language): Row => ({
      ...language,
      language: languageName(language.language_code, language.language),
      type_name_zh: languageLabel(language.language_code, language.language, "zh"),
      type_name_en: languageLabel(language.language_code, language.language, "en"),
      client_name: clientById.get(s(language.client_id || projectById.get(s(language.project_id))?.client_id))?.name ?? language.client_name,
      project_name:
        projectNameById.get(s(language.project_id)) ?? s(language.project_name),
      video_name:
        videoById.get(s(language.video_id))?.name ?? s(language.video_name),
    }),
  );
  const languageById = new Map(
    languages.map((language) => [s(language.id), s(language.language)]),
  );
  const localizeLanguageRows = (rows: Row[]): Row[] =>
    rows.map(
      (row): Row => ({
        ...row,
        language:
          languageById.get(s(row.language_project_id || row.id)) ??
          languageName(row.language_code, row.language),
      }),
    );
  const originalById = new Map(
    platform.folders.map((folder) => [s(folder.id), folder]),
  );
  const label = (folder: Row) => {
    if (folder.node_type === "client") return s(clientById.get(s(folder.client_id))?.name || folder.name);
    if (folder.node_type === "project") return projectNameById.get(s(folder.project_id)) || s(folder.name);
    if (folder.node_type === "video") return s(videoById.get(s(folder.video_id))?.name || folder.name);
    if (folder.node_type === "language") return languageById.get(s(folder.language_project_id)) || languageName(folder.language_code, folder.name);
    const raw =
      s(folder[locale === "zh" ? "name_zh" : "name_en"]) || s(folder.name);
    return n(folder.is_system) && s(folder.node_type) === "directory"
      ? raw.replace(/^\d{2}[_\s-]+/, "")
      : raw;
  };
  const pathFor = (folder: Row) => {
    const parts: string[] = [];
    let cursor: Row | undefined = folder;
    const visited = new Set<string>();
    while (cursor && !visited.has(s(cursor.id))) {
      visited.add(s(cursor.id));
      parts.unshift(label(cursor));
      cursor = originalById.get(s(cursor.parent_folder_id));
    }
    return `/${parts.join("/")}`;
  };
  const folders: Row[] = localizeProjectRows(platform.folders).map(
    (folder): Row => ({
      ...folder,
      name: label(folder),
      [locale === "zh" ? "name_zh" : "name_en"]: label(folder),
      path_cache: pathFor(folder),
    }),
  );
  const localizedById = new Map(
    folders.map((folder) => [s(folder.id), folder]),
  );
  const fileRecords: Row[] = localizeProjectRows(
    localizeLanguageRows(platform.fileRecords),
  ).map((file): Row => {
    const folder = localizedById.get(s(file.folder_id));
    return folder
      ? { ...file, folder_name: folder.name, folder_path: folder.path_cache }
      : file;
  });
  const localizedProjects: Row[] = projects.map(
    (project): Row => ({
      ...project,
      language_names: languages
        .filter((language) => language.project_id === project.id)
        .map((language) => s(language.language))
        .join(" / "),
    }),
  );
  return {
    ...platform,
    directories: localizedDirectories[locale],
    clients,
    projects: localizedProjects,
    videos,
    projectRequests: platform.projectRequests.map((request) => ({
      ...request,
      source_title: request.title,
      title: localizedRequestTitle(request, locale),
      client_name: clientById.get(s(request.client_id))?.name ?? request.client_name,
    })),
    projectRequestRevisions: platform.projectRequestRevisions.map((revision) => ({
      ...revision,
      source_title: revision.title,
      title: localizedRequestTitle(revision, locale),
    })),
    languages,
    folders,
    fileRecords,
    files: localizeProjectRows(localizeLanguageRows(platform.files)),
    pendingQuality: localizeProjectRows(
      localizeLanguageRows(platform.pendingQuality),
    ),
    quality: localizeProjectRows(localizeLanguageRows(platform.quality)),
    customerFeedback: localizeProjectRows(
      localizeLanguageRows(platform.customerFeedback),
    ).map(row => ({ ...row, source_summary: row.summary, summary: customerFeedbackSummary(row, locale) })),
    deliveryRecords: localizeProjectRows(
      localizeLanguageRows(platform.deliveryRecords),
    ),
    recycledFiles: localizeProjectRows(
      localizeLanguageRows(platform.recycledFiles),
    ).map(row => !s(row.project_id) && row.project_name === "素材库"
      ? { ...row, project_name: text[locale].assets }
      : row),
    recycledFolders: localizeProjectRows(platform.recycledFolders),
    shares: localizeProjectRows(platform.shares),
    publications: localizeProjectRows(platform.publications),
    checkpoints: localizeProjectRows(localizeLanguageRows(platform.checkpoints)),
    checkpointDrafts: localizeProjectRows(localizeLanguageRows(platform.checkpointDrafts)),
    handovers: localizeProjectRows(localizeLanguageRows(platform.handovers)),
    standards: localizeProjectRows(localizeLanguageRows(platform.standards)),
    notifications: localizeProjectRows(localizeLanguageRows(platform.notifications)).map(row => {
      const original = platform.projects.find(p => p.id === row.project_id);
      const oldName = s(original?.name);
      const key = locale === "zh" ? "body_zh" : "body_en";
      let body = s(row[key]);
      if (oldName && row.project_name) body = body.split(`“${oldName}”`).join(`“${s(row.project_name)}”`);
      const originalLanguage = platform.languages.find(l => l.id === row.target_id);
      if (originalLanguage?.language && row.language) body = body.split(s(originalLanguage.language)).join(s(row.language));
      return { ...row, [key]: body };
    }),
  };
}
type ClientFormField =
  | "name"
  | "legalName"
  | "region"
  | "industry"
  | "contactName"
  | "contactEmail"
  | "contactPhone";
type ClientFormErrors = Partial<Record<ClientFormField, string>>;
function validateClientForm(payload: Record<string, string>, locale: Locale) {
  const errors: ClientFormErrors = {};
  const required: Array<[ClientFormField, string, string]> = [
    ["name", "请输入客户名称。", "Enter a customer name."],
    ["legalName", "请输入公司全称。", "Enter the legal company name."],
    ["region", "请选择区域。", "Select a region."],
    ["industry", "请选择行业。", "Select an industry."],
  ];
  for (const [field, zh, en] of required)
    if (!payload[field]?.trim()) errors[field] = locale === "zh" ? zh : en;
  if (
    payload.contactEmail &&
    !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(payload.contactEmail.trim())
  )
    errors.contactEmail =
      locale === "zh"
        ? "请输入有效的邮箱地址。"
        : "Enter a valid email address.";
  if (
    payload.region &&
    !customerRegionOptions.some(([value]) => value === payload.region)
  )
    errors.region =
      locale === "zh"
        ? "请选择列表中的区域。"
        : "Select a region from the list.";
  if (
    payload.industry &&
    !customerIndustryOptions.some(([value]) => value === payload.industry)
  )
    errors.industry =
      locale === "zh"
        ? "请选择列表中的行业。"
        : "Select an industry from the list.";
  if (payload.contactPhone) {
    const digits = payload.contactPhone.replace(/\D/g, "");
    if (
      !/^\+?[0-9()\-\s]{7,24}$/.test(payload.contactPhone.trim()) ||
      digits.length < 7 ||
      digits.length > 15
    )
      errors.contactPhone =
        locale === "zh"
          ? "请输入有效的电话号码，例如 +60 12 345 6789。"
          : "Enter a valid phone number, for example +60 12 345 6789.";
  }
  return errors;
}

