function Panel({
  id,
  title,
  meta,
  children,
  className = "",
  actions,
  selection,
  dataList = false,
  inlineFilters = false,
}: {
  id?: string;
  title: string;
  meta?: string;
  children: ReactNode;
  className?: string;
  actions?: ReactNode;
  selection?: ReactNode;
  dataList?: boolean;
  inlineFilters?: boolean;
}) {
  if (dataList || className === "sales-list-panel") {
    const nodes = Children.toArray(children);
    const isControl = (node: ReactNode) => isValidElement<{className?: string}>(node) && (node.type === AdminFilters || /(?:filter-group|list-status-tabs)/.test(node.props.className || ""));
    const isTab = (node: ReactNode) => isValidElement<{className?: string}>(node) && /list-status-tabs/.test(node.props.className || "");
    const isPage = (node: ReactNode) => isValidElement(node) && node.type === Pagination;
    const filterNodes = nodes.filter(node => isControl(node) && !isTab(node));
    const findSearch = (node: ReactNode): ReactNode => {
      if (!isValidElement<{className?: string;children?: ReactNode}>(node)) return null;
      if (/(?:^| )(?:page-search|list-query-controls)(?: |$)/.test(node.props.className || "")) return node;
      return Children.toArray(node.props.children).map(findSearch).find(Boolean) || null;
    };
    const searchControl = filterNodes.map(findSearch).find(Boolean) || null;
    const separateSearch = (node: ReactNode): ReactNode => {
      if (!isValidElement<{className?: string;children?: ReactNode}>(node)) return node;
      if (/(?:^| )(?:page-search|list-query-controls)(?: |$)/.test(node.props.className || "")) return null;
      return node.props.children ? cloneElement(node, {}, Children.map(node.props.children, separateSearch)) : node;
    };
    const filters = filterNodes.map(separateSearch);
    return <div id={id} className="unified-list-layout">
      {nodes.filter(isTab)}
      <DataList className={`workbench-data-list ${className}`} ariaLabel={title} toolbar={searchControl} actions={actions} inlineFilters={inlineFilters}
        filters={filters}
        summary={selection || <><strong>{title}</strong>{meta && <span>{meta}</span>}</>}
        pagination={nodes.some(isPage) ? nodes.filter(isPage) : undefined}>
        {nodes.filter(node => !isControl(node) && !isPage(node))}
      </DataList>
    </div>;
  }
  return (
    <section id={id} className={`work-panel ${className}`}>
      <header>
        <span>{title}</span>
        {meta ? <span>{meta}</span> : null}
      </header>
      <div className="panel-body">{children}</div>
    </section>
  );
}
