function DragFilePicker({
  file,
  onFile,
  locale,
  accept,
  title,
  hint,
  compact = false,
  disabled = false,
}: {
  file: File | null;
  onFile: (file: File | null) => void;
  locale: Locale;
  accept?: string;
  title?: string;
  hint?: string;
  compact?: boolean;
  disabled?: boolean;
}) {
  return <div className={compact ? "upload-picker compact" : "upload-picker"}>
    <UploadDropzone locale={locale} accept={accept} disabled={disabled} title={title} hint={hint} onFiles={files => onFile(files[0])}/>
    {file && <UploadQueue locale={locale} items={[{id:"selected",name:file.name,size:file.size,progress:0,phase:"queued"}]} describe={()=>locale==="zh"?"待上传":"Ready to upload"} remove={disabled?undefined:()=>onFile(null)}/>}
  </div>;
}


function MultiDragFilePicker({
  files,
  onFiles,
  locale,
  accept,
  disabled = false,
}: {
  files: File[];
  onFiles: (files: File[]) => void;
  locale: Locale;
  accept?: string;
  disabled?: boolean;
}) {
  const addFiles = (incoming: File[]) => {
    if (disabled) return;
    const next = [...files];
    for (const file of incoming) if (!next.some(item=>item.name===file.name&&item.size===file.size&&item.lastModified===file.lastModified)) next.push(file);
    onFiles(next);
  };
  return <div className="request-document-picker">
    <UploadDropzone locale={locale} multiple accept={accept} maxBytes={25*1024*1024} disabled={disabled} onFiles={addFiles} title={locale==="zh"?"拖拽完整需求文档到这里，或点击选择":"Drop full requirement documents here, or click to browse"} hint={locale==="zh"?"可多选；单个文件不超过 25 MB":"Multiple files supported; 25 MB maximum per file"}/>
    <UploadQueue locale={locale} items={files.map((file,index)=>({id:String(index),name:file.name,size:file.size,progress:0,phase:"queued"}))} describe={()=>locale==="zh"?"待上传":"Ready to upload"} remove={disabled?undefined:id=>onFiles(files.filter((_,index)=>String(index)!==id))}/>
  </div>;
}

